import React, { useState, useEffect } from 'react';
import ProcessDetails from './ProcessDetails';
import ProcessChecklist from './ProcessChecklist';
import VisualizationRenderer from './VisualizationRenderer';
// import { fetchProcessDetails } from '../../../services/api'; // Placeholder

const ProcessVisualization = ({ processId }) => {
  const [processData, setProcessData] = useState(null); // Will hold data for details & checklist
  const [visualizationHtml, setVisualizationHtml] = useState(''); // HTML for graph
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  // Sample process data including a visualization graph (HTML string)
  const sampleProcessDataWithGraph = {
    id: processId,
    general_description: 'This is an example process for onboarding a new employee. It involves multiple departments.',
    process_steps: [
      'HR sends offer letter.',
      'Candidate accepts offer.',
      'Background check initiated.',
      'IT provisions equipment and access.',
      'Manager prepares onboarding plan.',
      'Day 1: Welcome and introductions.'
    ],
    scope: 'All new full-time employees in the US.',
    inputs: ['Candidate application', 'Offer template', 'Background check service'],
    outputs: ['Fully onboarded employee', 'Signed employment contract'],
    kpis: ['Time to onboard < 7 days', 'New hire satisfaction survey > 4.0/5.0'],
    roles_responsibilities: ['Recruiter: Manages offer process', 'Hiring Manager: Owns onboarding experience', 'IT: Provides technical setup'],
    exceptions_special_cases: ['For international hires, visa processing adds extra steps.'],
    // Simple HTML visualization example (e.g., a basic list or divs)
    visualization_graph: '<div style="padding:10px; border:1px solid green; text-align:center;"><h4>Simple Flow (HTML)</h4><p>Step 1 &rarr; Step 2 &rarr; Step 3</p></div>'
  };

  useEffect(() => {
    // Simulate fetching process details including visualization
    // In a real app, call: fetchProcessDetails(processId)
    console.log(`ProcessVisualization mounted for processId: ${processId}. Fetch details here.`);
    setIsLoading(true);
    setTimeout(() => { // Simulate API delay
      // For now, use sample data. Replace with API call.
      // const fetchedData = await fetchProcessDetails(processId);
      const fetchedData = sampleProcessDataWithGraph; // Using sample
      if (fetchedData) {
        setProcessData(fetchedData);
        setVisualizationHtml(fetchedData.visualization_graph || '');
      } else {
        setError('Process data not found.');
      }
      setIsLoading(false);
    }, 500);
  }, [processId]);

  // Callback for when AI updates process data (to be called from ChatInterface via parent)
  const handleProcessUpdate = (updatedData) => {
    setProcessData(prevData => ({ ...prevData, ...updatedData }));
    if (updatedData.visualization_graph) {
      setVisualizationHtml(updatedData.visualization_graph);
    }
    // Potentially, also update checklist based on updatedData
  };

  const vizPanelStyle = {
    display: 'flex',
    flexDirection: 'column',
    height: '100%', // Fill the parent panel
    backgroundColor: '#f9f9f9',
    padding: 'var(--spacing-unit, 16px)',
    boxSizing: 'border-box',
    gap: 'var(--spacing-unit, 16px)'
  };

  const detailsAndChecklistContainerStyle = {
    display: 'flex',
    flexDirection: 'row',
    gap: 'var(--spacing-unit, 16px)',
    maxHeight: '50%', // Example, adjust as needed
    overflow: 'hidden' // Prevent content from pushing graph down initially
  };

  const detailsContainerStyle = {
    flex: '2 1 0px', // Takes more space
    overflowY: 'auto',
    paddingRight: 'calc(var(--spacing-unit, 16px) / 2)', // For scrollbar space if needed
    border: '1px solid #e0e0e0',
    borderRadius: 'var(--border-radius)',
    padding: 'var(--spacing-unit)',
    backgroundColor: '#fff'
  };

  const checklistContainerStyle = {
    flex: '1 1 0px',
    overflowY: 'auto',
    paddingLeft: 'calc(var(--spacing-unit, 16px) / 2)',
    border: '1px solid #e0e0e0',
    borderRadius: 'var(--border-radius)',
    padding: 'var(--spacing-unit)',
    backgroundColor: '#fff'
  };

  const graphContainerStyle = {
    flexGrow: 1, // Takes remaining space
    display: 'flex', // To help center placeholder if needed
    flexDirection: 'column' // Ensure VisualizationRenderer can expand
  };

  if (isLoading) return <p>Loading process details...</p>;
  if (error) return <p style={{ color: 'red' }}>Error: {error}</p>;
  // Pass processData to children

  return (
    <div style={vizPanelStyle}>
      <h4 style={{ marginTop: 0, marginBottom: 0 }}>Process Details & Visualization</h4>
      <div style={detailsAndChecklistContainerStyle}>
        <div style={detailsContainerStyle}>
            <ProcessDetails processId={processId} processData={processData} onUpdate={handleProcessUpdate} />
        </div>
        <div style={checklistContainerStyle}>
            <ProcessChecklist processData={processData} />
        </div>
      </div>
      <div style={graphContainerStyle}>
        <VisualizationRenderer htmlContent={visualizationHtml} />
      </div>
    </div>
  );
};

export default ProcessVisualization;
